11	
12	import com.google.gson.FieldNamingPolicy;
13	import com.google.gson.Gson;
14	
15	import jadx.api.JadxArgs;
16	import jadx.core.codegen.json.mapping.JsonClsMapping;
17	import jadx.core.codegen.json.mapping.JsonFieldMapping;
18	import jadx.core.codegen.json.mapping.JsonMapping;
19	import jadx.core.codegen.json.mapping.JsonMthMapping;
20	import jadx.core.dex.info.ClassInfo;
21	import jadx.core.dex.info.MethodInfo;
22	import jadx.core.dex.nodes.ClassNode;
23	import jadx.core.dex.nodes.FieldNode;
24	import jadx.core.dex.nodes.MethodNode;
25	import jadx.core.dex.nodes.RootNode;
26	import jadx.core.utils.GsonUtils;
27	import jadx.core.utils.exceptions.JadxRuntimeException;
28	import jadx.core.utils.files.FileUtils;
29	
30	public class JsonMappingGen {
31		private static final Logger LOG = LoggerFactory.getLogger(JsonMappingGen.class);
32	
33		private static final Gson GSON = GsonUtils.defaultGsonBuilder()
34				.setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_DASHES)
35				.disableHtmlEscaping()
36				.create();
37	
38		public static void dump(RootNode root) {
39			JsonMapping mapping = new JsonMapping();
40			fillMapping(mapping, root);
41	
42			JadxArgs args = root.getArgs();
43			File outDirSrc = args.getOutDirSrc().getAbsoluteFile();
44			File mappingFile = new File(outDirSrc, "mapping.json");
45			FileUtils.makeDirsForFile(mappingFile);
46			try (Writer writer = new FileWriter(mappingFile)) {
47				GSON.toJson(mapping, writer);
48				LOG.info("Save mappings to {}", mappingFile.getAbsolutePath());
49			} catch (Exception e) {
50				throw new JadxRuntimeException("Failed to save mapping json", e);
51			}
52		}
53	
54		private static void fillMapping(JsonMapping mapping, RootNode root) {
55			List<ClassNode> classes = root.getClasses(true);
56			mapping.setClasses(new ArrayList<>(classes.size()));
57			for (ClassNode cls : classes) {
58				ClassInfo classInfo = cls.getClassInfo();
59				JsonClsMapping jsonCls = new JsonClsMapping();
60				jsonCls.setName(classInfo.getRawName());
61				jsonCls.setAlias(classInfo.getAliasFullName());
62				jsonCls.setInner(classInfo.isInner());
63				jsonCls.setJson(cls.getTopParentClass().getClassInfo().getAliasFullPath() + ".json");
64				if (classInfo.isInner()) {
65					jsonCls.setTopClass(cls.getTopParentClass().getClassInfo().getFullName());
66				}
67				addFields(cls, jsonCls);
68				addMethods(cls, jsonCls);
69				mapping.getClasses().add(jsonCls);
70			}
71		}
72	
73		private static void addMethods(ClassNode cls, JsonClsMapping jsonCls) {
74			List<MethodNode> methods = cls.getMethods();
75			if (methods.isEmpty()) {
76				return;
77			}
78			jsonCls.setMethods(new ArrayList<>(methods.size()));
79			for (MethodNode method : methods) {
80				JsonMthMapping jsonMethod = new JsonMthMapping();
81				MethodInfo methodInfo = method.getMethodInfo();
82				jsonMethod.setSignature(methodInfo.getShortId());
83				jsonMethod.setName(methodInfo.getName());
84				jsonMethod.setAlias(methodInfo.getAlias());
85				jsonMethod.setOffset("0x" + Long.toHexString(method.getMethodCodeOffset()));
86				jsonCls.getMethods().add(jsonMethod);
87			}
88		}
89	
90		private static void addFields(ClassNode cls, JsonClsMapping jsonCls) {
91			List<FieldNode> fields = cls.getFields();
92			if (fields.isEmpty()) {
93				return;
94			}
95			jsonCls.setFields(new ArrayList<>(fields.size()));
96			for (FieldNode field : fields) {
97				JsonFieldMapping jsonField = new JsonFieldMapping();
98				jsonField.setName(field.getName());
99				jsonField.setAlias(field.getAlias());
100				jsonCls.getFields().add(jsonField);
101			}
102		}
103	
104		private JsonMappingGen() {
105		}
106	}
